<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO prescriptions(patient_id,visit_id,prescribed_by,instructions,status) VALUES(?,?,?,?,"Active")');$s->execute([(int)$_POST['patient_id'],($_POST['visit_id']??'')?:null,($_POST['prescribed_by']??'')?:null,trim($_POST['instructions']??'')]);$pid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO prescription_items(prescription_id,medication_id,dose,frequency,duration,quantity) VALUES(?,?,?,?,?,?)');$s->execute([$pid,(int)$_POST['medication_id'],trim($_POST['dose']),trim($_POST['frequency']),trim($_POST['duration']),max(0,(float)$_POST['quantity'])]);$pdo->commit();audit('create','prescription',$pid);flash('Prescription created.');redirect('prescriptions.php');}catch(Throwable $e){$pdo->rollBack();flash('Could not create prescription: '.$e->getMessage());redirect('prescriptions.php?action=new');}}
if(isset($_GET['dispense'])){$id=(int)$_GET['dispense'];$pdo->beginTransaction();$s=$pdo->prepare('SELECT pi.medication_id,pi.quantity,pr.status FROM prescription_items pi JOIN prescriptions pr ON pr.id=pi.prescription_id WHERE pr.id=? FOR UPDATE');$s->execute([$id]);$items=$s->fetchAll();$ok=true;foreach($items as $it){$stock=(float)$pdo->query('SELECT stock_qty FROM medications WHERE id='.(int)$it['medication_id'].' FOR UPDATE')->fetchColumn();if($stock<(float)$it['quantity']){$ok=false;break;}}if($ok){foreach($items as $it){$pdo->prepare('UPDATE medications SET stock_qty=stock_qty-? WHERE id=?')->execute([(float)$it['quantity'],(int)$it['medication_id']]);}$pdo->prepare('UPDATE prescriptions SET status="Dispensed" WHERE id=?')->execute([$id]);$pdo->commit();audit('dispense','prescription',$id);flash('Prescription dispensed and stock updated.');}else{$pdo->rollBack();flash('Insufficient stock to dispense this prescription.');}redirect('prescriptions.php');}
$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();$meds=$pdo->query('SELECT id,name,unit,stock_qty FROM medications WHERE active=1 ORDER BY name')->fetchAll();$staff=$pdo->query("SELECT id,full_name FROM staff WHERE role IN ('Doctor','Nurse','Midwife') AND active=1 ORDER BY full_name")->fetchAll();$rows=$pdo->query('SELECT pr.*,p.patient_no,p.full_name, s.full_name prescriber,m.name medicine,pi.dose,pi.frequency,pi.duration,pi.quantity FROM prescriptions pr JOIN patients p ON p.id=pr.patient_id LEFT JOIN staff s ON s.id=pr.prescribed_by LEFT JOIN prescription_items pi ON pi.prescription_id=pr.id LEFT JOIN medications m ON m.id=pi.medication_id ORDER BY pr.created_at DESC LIMIT 150')->fetchAll();admin_header('Prescriptions','prescriptions.php');?><div class="pagehead"><div><h1>Prescriptions</h1><div class="muted">Prescribe medicines and dispense against recorded stock.</div></div><a class="btn" href="?action=new">New prescription</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Patient</label><select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['patient_no'].' — '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Prescriber</label><select name="prescribed_by"><option value="">Select clinician</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=e($s['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Medicine</label><select name="medication_id" required><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=e($m['name'].' — stock '.$m['stock_qty'].' '.$m['unit'])?></option><?php endforeach;?></select></div><div class="field"><label>Quantity</label><input type="number" step="0.01" min="0.01" name="quantity" required></div><div class="field"><label>Dose</label><input name="dose" placeholder="e.g. 1 tablet"></div><div class="field"><label>Frequency</label><input name="frequency" placeholder="e.g. 3 times daily"></div><div class="field"><label>Duration</label><input name="duration" placeholder="e.g. 5 days"></div><div class="field full"><label>Instructions</label><textarea name="instructions"></textarea></div></div><button style="margin-top:14px">Create prescription</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Date</th><th>Patient</th><th>Medicine</th><th>Dose</th><th>Frequency</th><th>Qty</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['patient_no'].' — '.$r['full_name'])?></td><td><?=e($r['medicine'])?></td><td><?=e($r['dose'])?></td><td><?=e($r['frequency'])?></td><td><?=e($r['quantity'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Active'):?><a class="btn secondary" href="?dispense=<?=$r['id']?>">Dispense</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php admin_footer();
